1	"use client";
2	
3	/**
4	 * activity-feed.tsx
5	 *
6	 * Collapsible panel showing a live stream of everything the auto-solve agent
7	 * is doing across all tickets.  Connects to the SSE feed on mount and keeps
8	 * the 50 most-recent entries in memory.
9	 *
10	 * Designed to sit at the bottom of the page as a persistent overlay that the
11	 * demo presenter can leave visible while navigating between pages.
12	 */
13	
14	import { useEffect, useRef, useState, useCallback } from "react";
15	import Link from "next/link";
16	import { cn } from "@repo/ui/lib/utils";
17	import {
18	  ChevronDown,
19	  ChevronUp,
20	  Activity,
21	  CheckCircle2,
22	  AlertTriangle,
23	  Info,
24	  XCircle,
25	  Mail,
26	  MessageCircle,
27	  FileText,
28	  ShieldAlert,
29	  TicketCheck,
30	  Loader2,
31	  Zap,
32	  BarChart3,
33	} from "lucide-react";
34	import { api } from "@/lib/api";
35	import { useAutoSolve } from "@/lib/auto-solve-context";
36	import type { AgentActivityEntry, ActivityEventType } from "@/lib/types";
37	
38	const MAX_ENTRIES = 50;
39	
40	// ---------------------------------------------------------------------------
41	// Severity → visual config
42	// ---------------------------------------------------------------------------
43	
44	const SEVERITY_CONFIG = {
45	  info:    { icon: Info,         cls: "text-blue-500",    bg: "bg-blue-500/10" },
46	  success: { icon: CheckCircle2, cls: "text-emerald-500", bg: "bg-emerald-500/10" },
47	  warning: { icon: AlertTriangle, cls: "text-amber-500",  bg: "bg-amber-500/10" },
48	  error:   { icon: XCircle,      cls: "text-red-500",     bg: "bg-red-500/10" },
49	} as const;
50	
51	// ---------------------------------------------------------------------------
52	// Action type → icon
53	// ---------------------------------------------------------------------------
54	
55	function ActionIcon({ actionType, eventType }: { actionType: string | null; eventType: ActivityEventType }) {
56	  if (eventType === "action_escalated") return <ShieldAlert className="h-3 w-3 text-amber-500" />;
57	  if (eventType === "action_confirmed" || eventType === "ticket_completed") return <CheckCircle2 className="h-3 w-3 text-emerald-500" />;
58	  if (eventType === "queue_started" || eventType === "queue_stopped") return <Zap className="h-3 w-3 text-blue-500" />;
59	  if (eventType === "ticket_error") return <XCircle className="h-3 w-3 text-red-500" />;
60	  switch (actionType) {
61	    case "send_vendor_email":  return <Mail className="h-3 w-3 text-muted-foreground" />;
62	    case "respond_to_tenant":  return <MessageCircle className="h-3 w-3 text-muted-foreground" />;
63	    case "send_owner_report":  return <FileText className="h-3 w-3 text-muted-foreground" />;
64	    case "escalate_to_human":  return <ShieldAlert className="h-3 w-3 text-amber-500" />;
65	    case "approve_ticket":     return <TicketCheck className="h-3 w-3 text-emerald-500" />;
66	    default:                   return <Activity className="h-3 w-3 text-muted-foreground" />;
67	  }
68	}
69	
70	// ---------------------------------------------------------------------------
71	// Single feed entry row
72	// ---------------------------------------------------------------------------
73	
74	function FeedEntry({ entry }: { entry: AgentActivityEntry }) {
75	  const sev = SEVERITY_CONFIG[entry.severity] ?? SEVERITY_CONFIG.info;
76	  const SevIcon = sev.icon;
77	
78	  return (
79	    <div
80	      className={cn(
81	        "flex items-start gap-2 rounded-md px-3 py-2 text-xs transition-colors",
82	        entry.severity === "warning" && "bg-amber-500/5 border border-amber-500/20",
83	        entry.severity === "error" && "bg-red-500/5 border border-red-500/20",
84	      )}
85	    >
86	      {/* Severity icon */}
87	      <SevIcon className={cn("mt-0.5 h-3 w-3 shrink-0", sev.cls)} />
88	
89	      {/* Content */}
90	      <div className="min-w-0 flex-1">
91	        <div className="flex items-center gap-1.5">
92	          <ActionIcon actionType={entry.actionType} eventType={entry.eventType} />
93	          {entry.ticketNum && (
94	            <Link
95	              href={`/ticket/${entry.ticketId}`}
96	              className="font-mono text-[10px] font-medium text-foreground/80 hover:text-foreground hover:underline"
97	              onClick={(e) => e.stopPropagation()}
98	            >
99	              {entry.ticketNum}
100	            </Link>
101	          )}
102	          <span className="truncate text-muted-foreground">{entry.description.replace(/^\[.*?\]\s*/, "")}</span>
103	        </div>
104	      </div>
105	
106	      {/* Timestamp */}
107	      <span className="shrink-0 font-mono text-[10px] tabular-nums text-muted-foreground/60">
108	        {entry.createdAt ? new Date(entry.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }) : ""}
109	      </span>
110	    </div>
111	  );
112	}
113	
114	// ---------------------------------------------------------------------------
115	// Main component
116	// ---------------------------------------------------------------------------
117	
118	export function ActivityFeed() {
119	  const [collapsed, setCollapsed] = useState(true);
120	  const [entries, setEntries] = useState<AgentActivityEntry[]>([]);
121	  const [unread, setUnread] = useState(0);
122	  const scrollRef = useRef<HTMLDivElement>(null);
123	  const { autoSolve, queueStatus, summary, openSummary } = useAutoSolve();
124	
125	  // Load initial recent entries
126	  useEffect(() => {
127	    api.agentQueue.recentFeed(50).then((data) => {
128	      // API returns newest-first; reverse for chronological display
129	      setEntries([...data].reverse());
130	    }).catch(() => {});
131	  }, []);
132	
133	  // Connect to SSE feed for live updates
134	  useEffect(() => {
135	    let cancelled = false;
136	    const ctrl = new AbortController();
137	
138	    const connect = async () => {
139	      try {
140	        await api.agentQueue.streamFeed({
141	          signal: ctrl.signal,
142	          onActivity: (entry) => {
143	            if (cancelled) return;
144	            // Skip pure queue_status events (they have no display-worthy content)
145	            if (entry.eventType === "queue_status") return;
146	            setEntries((prev) => {
147	              const next = [...prev, entry].slice(-MAX_ENTRIES);
148	              return next;
149	            });
150	            if (collapsed) {
151	              setUnread((n) => n + 1);
152	            }
153	          },
154	        });
155	      } catch {
156	        if (!cancelled) setTimeout(connect, 3000);
157	      }
158	    };
159	    connect();
160	    return () => { cancelled = true; ctrl.abort(); };
161	  }, [collapsed]);
162	
163	  // Auto-scroll to bottom when new entries arrive and feed is open
164	  useEffect(() => {
165	    if (!collapsed && scrollRef.current) {
166	      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
167	    }
168	  }, [entries, collapsed]);
169	
170	  // Reset unread count when opened
171	  const handleToggle = useCallback(() => {
172	    setCollapsed((v) => {
173	      if (v) setUnread(0);
174	      return !v;
175	    });
176	  }, []);
177	
178	  return (
179	    <div
180	      className={cn(
181	        "fixed bottom-0 right-4 z-40 flex w-96 flex-col rounded-t-xl border bg-background shadow-2xl transition-all duration-200",
182	        collapsed ? "h-10" : "h-80"
183	      )}
184	    >
185	      {/* Header bar */}
186	      <button
187	        onClick={handleToggle}
188	        className="flex h-10 shrink-0 items-center justify-between gap-2 rounded-t-xl px-4 hover:bg-accent/50 transition-colors"
189	      >
190	        <div className="flex items-center gap-2">
191	          <Activity className="h-3.5 w-3.5 text-muted-foreground" />
192	          <span className="text-xs font-semibold">Agent Activity</span>
193	          {autoSolve && (
